records.command:
mkdir -p classic/rust/crates/timeline/examples
cat > classic/rust/crates/timeline/examples/noise_probe.rs <<'RS'
use timeline::*;
fn main() {
 let evidence:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(".local/smart-takes-2026-10-29/audio-evidence.json").unwrap()).unwrap();
 let mut frames:Vec<AudioAnalysisFrame>=serde_json::from_value(evidence[0]["frames"].clone()).unwrap();
 let offset=frames[0].start;
 for f in &mut frames {f.start-=offset;f.end-=offset;}
 let bundle:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(".local/smart-takes-2026-10-29/session-bundle.json").unwrap()).unwrap();
 let words=bundle["archive"]["classic"]["document"]["scenes"][0]["takeAssembly"]["sourceWords"].as_array().unwrap().iter().enumerate().map(|(i,w)| TranscriptWordTiming {word_index:i as u32,start:w["start"].as_f64().unwrap()/120000.0-offset,end:w["end"].as_f64().unwrap()/120000.0-offset}).collect();
 let duration=frames.last().unwrap().end;
 let out=analyze_smart_audio_silence(AnalyzeSmartAudioSilenceOptions {frames,duration_seconds:duration,transcript_words:words,settings:SmartAudioSilenceSettings{min_silence_seconds:0.01,speech_padding_seconds:0.08,bridge_gap_seconds:0.12}});
 println!("{}",serde_json::to_string(&out).unwrap());
}
RS
cargo run -q --manifest-path classic/Cargo.toml -p timeline --example noise_probe > .local/smart-takes-2026-10-29/noise-probe.json
